create policy "mods follow car visibility" on public.mod_items
  as permissive
  for select
  to public
  using ((EXISTS ( SELECT 1
   FROM public.cars c
  WHERE c.id = mod_items.car_id AND (c.is_public OR c.owner_id = (( SELECT auth.uid() AS uid))))));
